69	    /**
70	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
71	     * at least one dot and no whitespace on either side.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization. Keys are the
78	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
79	     * expanded form.
80	     */
81	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
82	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
